css:
.cj{--ink:#1d2530;--mut:#5b6573;--card:#f6f4ef;--acc:#c8662a;--line:#d8d3c8;display:flex;flex-direction:column;gap:10px;max-width:900px;margin:0 auto;color:var(--ink);font:14px/1.4 system-ui,sans-serif}
html[data-theme=dark] .cj{--ink:#e6e9ee;--mut:#9aa4b2;--card:#1b2028;--acc:#ec8c46;--line:#343b47}
.cj-stage{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:6px;position:relative}
#cj-svg{display:block;width:100%;height:auto}
.cj-view{margin:2px 6px 0;font-size:12px;color:var(--mut)}
.cj-ed{stroke-width:.55;stroke-linejoin:round}
.cj-sm{stroke-width:.35}
.cj-sil{stroke-width:.7;fill:none}
.cj-tick{stroke-width:.8}
.cj-tl{font-size:9px;fill:var(--mut);text-anchor:middle}
.cj-lab{font-size:10px;font-weight:600;fill:var(--ink);paint-order:stroke;stroke:var(--card);stroke-width:3px}
.cj-dot{fill:var(--acc);stroke:var(--card);stroke-width:1}
.cj-ctl{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px 16px;align-items:center}
.cj-ctl label{display:flex;flex-direction:column;gap:2px;font-size:13px;color:var(--mut)}
.cj-ctl input[type=range]{width:100%;accent-color:var(--acc)}
.cj-btns{display:flex;flex-wrap:wrap;gap:6px}
.cj-btns button{font:inherit;padding:6px 12px;border-radius:7px;border:1px solid var(--line);background:var(--card);color:var(--ink);cursor:pointer}
.cj-btns button[aria-pressed=true],.cj-btns #play{border-color:var(--acc)}
.cj-read{display:flex;flex-wrap:wrap;gap:4px 12px;font:13px/1.4 ui-monospace,monospace}
.cj-acc{color:var(--acc);font-weight:700}
.cj-plot{width:100%;max-width:520px;height:auto;background:var(--card);border:1px solid var(--line);border-radius:8px}
.cj-ax{stroke:var(--mut);stroke-dasharray:3 3;stroke-width:.7}
.cj-pl{font-size:9px;fill:var(--mut)}
.cj-curve{fill:none;stroke:var(--acc);stroke-width:1.6}
.cj-mark{fill:var(--acc);stroke:var(--card);stroke-width:1.2}
.cj-status{margin:0;font-size:12px;color:var(--mut)}
.cj-det summary{cursor:pointer;color:var(--mut);font-size:13px}
.cj-det p{margin:6px 0 0;font-size:13px}

