// Cardan joint model. Joint centre at origin, shafts horizontal at z=0.
// Input axis a1=+x (shaft on -x side). Output axis a2=[cos b,-sin b,0] (shaft on + side),
// swivel arm pivots about vertical z through the centre. Base top at z=-BASE_Z.
// Cross pins: e1 (input yoke bores) and e2=unit(a2 x e1) (output yoke bores).
export const DIM = { R_IN: 22, R_OUT: 30, TRUN_R: 6, CUP_R: 9, EAR_W: 12, CROTCH: 36, HUB0: 70, HUB_R: 17,
  SHAFT_R: 9, SHAFT_LEN: 158, BRG_S: 130, BRG_HALF: 14, BASE_Z: 62, CROSS_HALF: 9, BETA_MAX: 40 };
const D2R = Math.PI / 180;
export const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
export const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
export const unit = (a) => { const l = Math.hypot(...a) || 1; return a.map((x) => x / l); };
const rot = (v, ax, t) => { const c = Math.cos(t), s = Math.sin(t), x = cross(ax, v), d = dot(ax, v);
  return v.map((vi, i) => vi * c + x[i] * s + ax[i] * d * (1 - c)); };
const wrap = (a) => Math.atan2(Math.sin(a), Math.cos(a));

export function createState() { return { beta: 25, theta: 0, playing: false, rpm: 30, blocked: false, inspect: false }; }
export function setBeta(s, deg) {
  const d = Number(deg);
  if (!(d >= 0) || d > DIM.BETA_MAX) return { ...s, blocked: true };
  return { ...s, beta: d, blocked: false };
}
export function setRpm(s, r) { return { ...s, rpm: Math.min(60, Math.max(5, Number(r) || 30)) }; }
export function step(s, dt) { return { ...s, theta: (s.theta + s.rpm * 6 * dt) % 360 }; }
export function togglePlay(s) { return { ...s, playing: !s.playing }; }
export function toggleInspect(s) { return { ...s, inspect: !s.inspect }; }

export function pose(betaDeg, thetaDeg) {
  const b = betaDeg * D2R, t1 = thetaDeg * D2R;
  const a1 = [1, 0, 0], a2 = [Math.cos(b), -Math.sin(b), 0], z = [0, 0, 1];
  const e1 = rot(z, a1, t1);
  const e2 = unit(cross(a2, e1));
  const e20 = cross(a2, z);
  const t2raw = Math.atan2(dot(e2, cross(a2, e20)), dot(e2, e20));
  const t2 = t1 + wrap(t2raw - t1);
  const psi1 = Math.asin(dot(e2, a1)) / D2R, psi2 = Math.asin(dot(e1, a2)) / D2R;
  return { a1, a2, e1, e2, n: cross(e1, e2), t1: thetaDeg, t2: t2 / D2R,
    yokeIn: { a: a1, e: e1, t: cross(a1, e1) }, yokeOut: { a: a2, e: e2, t: cross(a2, e2) }, psi1, psi2 };
}
// numeric speed ratio from the vector construction
export function ratio(betaDeg, thetaDeg) {
  const h = 0.01; return (pose(betaDeg, thetaDeg + h).t2 - pose(betaDeg, thetaDeg - h).t2) / (2 * h);
}
export function ratioClosed(betaDeg, thetaDeg) {
  const c = Math.cos(betaDeg * D2R), s = Math.sin(betaDeg * D2R), st = Math.sin(thetaDeg * D2R);
  return c / (1 - s * s * st * st);
}
export function curve(betaDeg, n = 72) { return Array.from({ length: n + 1 }, (_, i) => [i * 360 / n, ratio(betaDeg, i * 360 / n)]); }
// Clearance: output ear tip (rounded end beyond centre) vs input crotch face, over a cycle
export function earClearance(betaDeg, thetaDeg) {
  const p = pose(betaDeg, thetaDeg); let m = Infinity;
  for (const sg of [1, -1]) for (const r of [DIM.R_IN, DIM.R_OUT]) for (const w of [-1, 1]) {
    const tip = [0, 1, 2].map((i) => sg * r * p.e2[i] - DIM.EAR_W * p.a2[i] + w * DIM.EAR_W * p.yokeOut.t[i]);
    m = Math.min(m, tip[0] + DIM.CROTCH);
  }
  return m;
}
// ---- Support / joint layout (consumed verbatim by geometry.mjs) ----
// Split pillow block: housing top = split plane through the shaft axis (cap removed), brass half shell
// seats the shaft from below. Output block stands on the swivel arm (top at -BASE_Z+ARM_T).
export const LAYOUT = { ARM_T: 6, ARM_HALF_W: 42, ARM_LEN: 182, ARM_NOSE_R: 30, PIN_R: 11,
  BRASS_IN: DIM.SHAFT_R + 0.4, BRASS_OUT: 13, HOUSE_HALF: 24, FOOT_HALF_U: 36, FOOT_T: 7, FOOT_HALF_S: DIM.BRG_HALF + 4,
  // needle bearing in each yoke ear: trunnion r → needle band → cup shell → ear bore (= cup outer)
  NEEDLE_OUT: 7.6, CUP_END: DIM.R_OUT + 4, CAP_END: DIM.R_OUT + 5.5, TRUN_TIP: DIM.R_OUT + 3.5 };
export function supports(betaDeg) {
  const b = betaDeg * D2R, a1 = [1, 0, 0], a2 = [Math.cos(b), -Math.sin(b), 0];
  const mk = (A, dir, standZ) => {
    const centre = A.map((x) => x * dir * DIM.BRG_S);
    const u = unit(cross([0, 0, 1], A));
    return { axis: A, dir, centre, u, standZ, floor: -standZ, s0: dir * DIM.BRG_S - DIM.BRG_HALF, s1: dir * DIM.BRG_S + DIM.BRG_HALF,
      footCorners: [-1, 1].flatMap((i) => [-1, 1].map((j) => [0, 1, 2].map((k) => centre[k] + A[k] * i * LAYOUT.FOOT_HALF_S + u[k] * j * LAYOUT.FOOT_HALF_U + (k === 2 ? standZ : 0)))) };
  };
  return { in: mk(a1, -1, -DIM.BASE_Z), out: mk(a2, 1, -DIM.BASE_Z + LAYOUT.ARM_T), arm: { axis: a2, u: unit(cross([0, 0, 1], a2)), top: -DIM.BASE_Z + LAYOUT.ARM_T } };
}
// distance of point q from the shaft line through origin along A
export function lineDist(q, A) { const d = dot(q, A); return Math.hypot(...q.map((x, i) => x - d * A[i])); }
export function status(s) {
  const p = pose(s.beta, s.theta), r = ratio(s.beta, s.theta);
  return { p, r, text: s.blocked ? `Blocked: yokes would collide beyond ${DIM.BETA_MAX}°` : `Shaft angle ${s.beta.toFixed(0)}°` };
}

