import * as M from './model.mjs';
const { DIM } = M;
export function verify() {
  const out = [], add = (name, passed, detail = '') => out.push({ name, passed: !!passed, detail });
  let orth = 0, closure = 0, rmin = Infinity, rmax = -Infinity, psiMax = 0, clr = Infinity, mono = true;
  const B = 30;
  let prev = M.pose(B, 0).t2;
  for (let th = 0; th <= 360; th += 3) {
    const p = M.pose(B, th);
    orth = Math.max(orth, Math.abs(M.dot(p.e1, p.e2)), Math.abs(M.dot(p.e1, p.a1)), Math.abs(M.dot(p.e2, p.a2)));
    // trunnion tips of the cross coincide with yoke bore centres on both yokes
    for (const sg of [1, -1]) {
      const tipIn = p.e1.map((x) => x * sg * DIM.R_OUT), boreIn = p.yokeIn.e.map((x) => x * sg * DIM.R_OUT);
      closure = Math.max(closure, Math.hypot(...tipIn.map((v, i) => v - boreIn[i])));
    }
    const r = M.ratio(B, th);
    rmin = Math.min(rmin, r); rmax = Math.max(rmax, r);
    psiMax = Math.max(psiMax, Math.abs(p.psi1), Math.abs(p.psi2));
    if (p.t2 < prev - 1e-9) mono = false; prev = p.t2;
  }
  for (let th = 0; th < 360; th += 5) clr = Math.min(clr, M.earClearance(DIM.BETA_MAX, th));
  const c = Math.cos(B * Math.PI / 180);
  add('cross arms stay perpendicular to each other and to their shafts', orth < 1e-9, `max ${orth.toExponential(2)}`);
  add('trunnion centres close on both yoke bores', closure < 1e-9);
  add('speed ratio spans cos β … 1/cos β', Math.abs(rmin - c) < 2e-3 && Math.abs(rmax - 1 / c) < 2e-3, `${rmin.toFixed(4)}..${rmax.toFixed(4)}`);
  let dev = 0; for (let th = 0; th < 360; th += 7) dev = Math.max(dev, Math.abs(M.ratio(B, th) - M.ratioClosed(B, th)));
  add('vector kinematics matches closed-form ratio', dev < 1e-3, dev.toExponential(2));
  add('output completes one turn per input turn', mono && Math.abs(M.pose(B, 360).t2 - 360) < 1e-6);
  add('cross rocks in its bearings by ±β', Math.abs(psiMax - B) < 0.3, psiMax.toFixed(2));
  add('ear clearance positive at limit angle', clr > 1, clr.toFixed(2));
  let ok0 = 0; for (let th = 0; th < 360; th += 10) ok0 = Math.max(ok0, Math.abs(M.ratio(0, th) - 1));
  add('straight alignment gives uniform speed', ok0 < 1e-6);
  let s = M.createState(); const b0 = s.beta;
  s = M.setBeta(s, 45);
  add('beyond limit is blocked and keeps angle', s.blocked && s.beta === b0);
  s = M.setBeta(s, 35);
  add('valid angle accepted and clears block', !s.blocked && s.beta === 35);
  let t = M.createState(); t = M.step(t, 1);
  add('playback advances input angle', t.theta > 0 && Math.abs(t.theta - t.rpm * 6) < 1e-9);
  add('bearing interval engages shaft', DIM.BRG_S + DIM.BRG_HALF < DIM.SHAFT_LEN && DIM.BRG_S - DIM.BRG_HALF > DIM.HUB0);
  return out;
}
export function verifyExtra1() {
  const out = [], add = (name, passed, detail = '') => out.push({ name, passed: !!passed, detail });
  const L = M.LAYOUT;
  let axisErr = 0, standErr = 0, footOut = -Infinity, seatGap = Infinity;
  for (let b = 0; b <= DIM.BETA_MAX; b += 5) for (let th = 0; th < 360; th += 45) {
    const S = M.supports(b), p = M.pose(b, th);
    // bearing centres lie on the shaft axes actually used by the yokes in that pose
    axisErr = Math.max(axisErr, M.lineDist(S.in.centre, p.yokeIn.a), M.lineDist(S.out.centre, p.yokeOut.a));
    // feet touch base top / swivel arm top
    standErr = Math.max(standErr, Math.abs(S.in.standZ + DIM.BASE_Z), Math.abs(S.out.standZ - S.arm.top));
    // output foot footprint inside the swivel arm rectangle
    for (const c of S.out.footCorners) {
      const s = M.dot(c, S.arm.axis), w = Math.abs(M.dot(c, S.arm.u));
      footOut = Math.max(footOut, w - L.ARM_HALF_W, s - L.ARM_LEN, -s);
    }
    seatGap = Math.min(seatGap, L.BRASS_IN - DIM.SHAFT_R);
  }
  add('bearing centres lie on both shaft axes over β and θ', axisErr < 1e-9, axisErr.toExponential(2));
  add('pillow feet rest on base and swivel arm (3D contact)', standErr < 1e-9);
  add('output pillow footprint stays on swivel arm', footOut <= 0, footOut.toFixed(2));
  add('brass seat clearance 0 < c < 1 around shaft', seatGap > 0 && seatGap < 1, seatGap.toFixed(2));
  add('bearing housing encloses the brass shell', L.HOUSE_HALF > L.BRASS_OUT && L.BRASS_OUT > L.BRASS_IN);
  // trunnion engages needle band inside the cup, cup sits in the ear bore
  let tipErr = 0;
  for (let th = 0; th < 360; th += 30) { const p = M.pose(30, th);
    for (const e of [p.e1, p.e2]) { const tip = e.map((x) => x * L.TRUN_TIP); tipErr = Math.max(tipErr, Math.abs(Math.hypot(...tip) - L.TRUN_TIP)); } }
  add('trunnion tip inside cup span within the ear', L.TRUN_TIP > DIM.R_OUT && L.TRUN_TIP < L.CUP_END && tipErr < 1e-9);
  add('needle band between trunnion and cup bore', DIM.TRUN_R < L.NEEDLE_OUT && L.NEEDLE_OUT < DIM.CUP_R && DIM.CUP_R < DIM.EAR_W);
  return out;
}

