import * as M from './model.mjs';
import * as Gm from './geometry.mjs';

export function mount(root, env) {
  let st = M.createState(), theme = env.theme || 'light', raf = 0, last = 0, visible = true, camKey = '', P = null, W = 360, H = 280;
  root.innerHTML = `<div class="cj">
  <div class="cj-stage"><svg id="cj-svg" role="img" aria-label="Cardan universal joint with two yokes, cross and sectioned pillow-block supports"></svg>
  <p class="cj-view" id="cj-view">Full assembly · pillow-block caps removed (section)</p></div>
  <div class="cj-ctl">
   <label>Shaft angle β <input id="beta" type="range" min="0" max="45" step="1" value="${st.beta}"></label>
   <label>Input angle θ₁ <input id="theta" type="range" min="0" max="359" step="1" value="0"></label>
   <div class="cj-btns"><button id="play" type="button">Play</button><button id="inspect" type="button" aria-pressed="false">Inspect joints</button><button id="reset" type="button">Reset</button></div>
  </div>
  <div class="cj-read" id="readout" aria-live="polite"></div>
  <svg id="cj-plot" class="cj-plot" viewBox="0 0 320 90" role="img" aria-label="Output to input speed ratio over one input turn"></svg>
  <p class="cj-status" id="status" role="status"></p>
  <details class="cj-det"><summary>What the section shows</summary><p>The caps of both pillow blocks are removed down to the shaft axis: the hatched light faces are the cut housing, the brass half-shells are the plain bearings carrying each shaft. The orange cross carries four trunnions running in needle cups pressed into the yoke ears. The output support stands on a swivel arm pinned under the joint centre, so the angle β is read on the protractor.</p></details>
 </div>`;
  const $ = (id) => root.querySelector('#' + id);
  const svg = $('cj-svg'), plot = $('cj-plot');
  function frame() {
    const w = Math.max(300, Math.min(900, root.clientWidth || 360));
    W = Math.round(w); H = Math.round(st.inspect ? W * 0.7 : W * 0.66);
    const key = `${st.inspect}|${W}`;
    if (key !== camKey) { camKey = key; P = Gm.camera(st.inspect, W, H); svg.setAttribute('viewBox', `0 0 ${W} ${H}`); }
  }
  function render() {
    frame();
    svg.innerHTML = Gm.draw(st, P, theme);
    const s = M.status(st), p = s.p, d = ((p.t2 - p.t1) % 360 + 540) % 360 - 180;
    $('readout').innerHTML = `<span>β = ${st.beta.toFixed(0)}°</span><span>θ₁ = ${p.t1.toFixed(1)}°</span><span>θ₂ = ${(((p.t2 % 360) + 360) % 360).toFixed(1)}°</span><span>θ₂−θ₁ = ${d.toFixed(2)}°</span><span class="cj-acc">ω₂/ω₁ = ${s.r.toFixed(3)}</span><span>ψ₁ = ${p.psi1.toFixed(1)}° · ψ₂ = ${p.psi2.toFixed(1)}°</span>`;
    $('status').textContent = (s.text + (st.inspect ? ' · Inspection view (close-up of the cross)' : '') + (st.playing ? ' · running' : ' · paused'));
    $('cj-view').textContent = st.inspect ? 'Optional inspection view · cross, trunnions and needle cups' : 'Full assembly · pillow-block caps removed (section)';
    $('play').textContent = st.playing ? 'Pause' : 'Play';
    $('inspect').setAttribute('aria-pressed', String(st.inspect));
    $('beta').value = String(st.beta); $('theta').value = String(Math.round(st.theta) % 360);
    const c = M.curve(st.beta, 90), lo = 0.7, hi = 1.4, y = (r) => 80 - (r - lo) / (hi - lo) * 72, x = (t) => 20 + t / 360 * 292;
    plot.innerHTML = `<line x1="20" x2="312" y1="${y(1)}" y2="${y(1)}" class="cj-ax"/><text x="2" y="${y(1) + 3}" class="cj-pl">1</text>
     <path d="M${c.map(([t, r]) => `${x(t).toFixed(1)},${y(r).toFixed(1)}`).join('L')}" class="cj-curve"/>
     <circle cx="${x(st.theta % 360)}" cy="${y(s.r)}" r="3.5" class="cj-mark"/><text x="22" y="10" class="cj-pl">ω₂/ω₁ over one input turn</text>`;
  }
  function loop(t) {
    if (!st.playing) { raf = 0; return; }
    const dt = Math.min(0.1, (t - last) / 1000); last = t;
    if (visible) { st = M.step(st, env.reducedMotion ? dt * 0.5 : dt); render(); }
    raf = requestAnimationFrame(loop);
  }
  const start = () => { if (!raf) { last = performance.now(); raf = requestAnimationFrame(loop); } };
  const stop = () => { if (raf) cancelAnimationFrame(raf); raf = 0; };
  $('beta').addEventListener('input', (e) => { st = M.setBeta(st, e.target.value); render(); });
  $('theta').addEventListener('input', (e) => { st = { ...st, theta: Number(e.target.value) }; render(); });
  $('play').addEventListener('click', () => { st = M.togglePlay(st); st.playing ? start() : stop(); render(); });
  $('inspect').addEventListener('click', () => { st = M.toggleInspect(st); render(); });
  $('reset').addEventListener('click', () => { stop(); st = M.createState(); render(); });
  const onEnv = (e) => { const d = e.detail || {}; if (d.theme) theme = d.theme; if ('visible' in d) visible = d.visible; if ('reducedMotion' in d) env = { ...env, reducedMotion: d.reducedMotion }; if (visible && st.playing) last = performance.now(); render(); };
  root.addEventListener('figure:environment', onEnv);
  const ro = new ResizeObserver(() => { const w = Math.round(root.clientWidth); if (w && Math.abs(w - W) > 2) render(); });
  ro.observe(root);
  render();
  return () => { stop(); ro.disconnect(); root.removeEventListener('figure:environment', onEnv); root.innerHTML = ''; };
}

