import * as k from '/kit/iso-kit.mjs';
import { mView, mLight, mBand } from '/kit/facets.mjs';
import { orderSurfaces } from '/leitor/occlusion.mjs';
import { DIM, pose, cross, dot, unit } from './model.mjs';

const lin = (o, a, u, v) => (s, x, y) => [0, 1, 2].map((i) => o[i] + a[i] * s + u[i] * x + v[i] * y);
const perp = (a) => { const u = unit(Math.abs(a[2]) > 0.9 ? cross(a, [1, 0, 0]) : cross([0, 0, 1], a)); return [u, cross(a, u)]; };
const area = (r) => r.reduce((s, p, i) => { const q = r[(i + 1) % r.length]; return s + p[0] * q[1] - q[0] * p[1]; }, 0);
export const circ = (r, n, a0 = 0, a1 = 2 * Math.PI, cx = 0, cy = 0) => Array.from({ length: n }, (_, i) => { const t = a0 + (a1 - a0) * i / n; return [cx + r * Math.cos(t), cy + r * Math.sin(t)]; });

// convex prism: ring [x,y] in (u,v) plane, from s0 to s1 along a. Returns faces + silhouette segments.
export function prism(F, ring, s0, s1, mat, V, opt = {}) {
  const r = area(ring) > 0 ? ring : [...ring].reverse();
  const at = lin(F.o, F.a, F.u, F.v), out = [];
  const nrm = r.map((p, j) => { const q = r[(j + 1) % r.length]; return unit([0, 1, 2].map((i) => F.u[i] * (q[1] - p[1]) - F.v[i] * (q[0] - p[0]))); });
  const smooth = !!opt.smooth, m = r.length;
  out.push({ points: r.map((p) => at(s1, ...p)).reverse().reverse(), n: F.a, mat: opt.capMat || mat, edge: true });
  out.push({ points: r.map((p) => at(s0, ...p)).reverse(), n: F.a.map((x) => -x), mat: opt.capMat || mat, edge: true });
  r.forEach((p, j) => {
    const q = r[(j + 1) % m], n = nrm[j];
    out.push({ points: [at(s0, ...p), at(s0, ...q), at(s1, ...q), at(s1, ...p)], n, mat: (opt.sideMat && opt.sideMat(j)) || mat, edge: !smooth });
    if (smooth) { const nn = nrm[(j + 1) % m], vis = dot(n, V) > 0, vis2 = dot(nn, V) > 0;
      if (vis !== vis2) out.push({ segment: true, points: [at(s0, ...q), at(s1, ...q)] }); }
  });
  return out;
}
export function cyl(o, a, rad, s0, s1, mat, V, n = 18) {
  const [u, v] = perp(a); return prism({ o, a, u, v }, circ(rad, n), s0, s1, mat, V, { smooth: true });
}
// annular sectors (convex quads) between angles
export function sectors(F, r0, r1, a0, a1, n, s0, s1, mat, V, endMat) {
  const out = [];
